/** Canonical Glass plus a private tool/menu; only real interaction/settings packets drive edits. */
@EventBusSubscriber(modid="vandorlabs")
public final class CopifierGlassClientFixture {
 static final BlockPos SOURCE=new BlockPos(0,96,0),TARGET=SOURCE.east(2),PEER=TARGET.above(),ACK=SOURCE.east(5);private static NativeGlassEntity first,second;private static CompoundTag water,lava;private static java.util.UUID actor;private static int stage;
 static boolean enabled(){return "copifier-glass-client".equals(System.getProperty("vandorlabs.transmitterPhase"));}
 private static void need(boolean yes,String why){if(!yes)throw new IllegalStateException("Copifier Glass server stage="+stage+": "+why);}
 @EventBusSubscriber(modid="vandorlabs",bus=EventBusSubscriber.Bus.MOD)public static final class Registration {
  @SubscribeEvent public static void packets(net.neoforged.neoforge.network.event.RegisterPayloadHandlersEvent event){if(!enabled())return;NativeCopifierPayload.register(event);NativeCopifierUndoPayload.register(event);event.registrar("1").playToServer(Mode.TYPE,new StreamCodec<RegistryFriendlyByteBuf,Mode>(){public Mode decode(RegistryFriendlyByteBuf b){if(b.readableBytes()!=1)throw new IllegalArgumentException();int n=b.readUnsignedByte();if(n>2)throw new IllegalArgumentException();return new Mode(n);}public void encode(RegistryFriendlyByteBuf b,Mode p){b.writeByte(p.operation);}},(p,c)->c.enqueueWork(()->{if(c.player() instanceof ServerPlayer player)apply(player,p.operation);}));}
 }
 public record Mode(int operation) implements CustomPacketPayload {static final Type<Mode> TYPE=new Type<>(ResourceLocation.parse("vandorlabs:copifier_glass_fixture_mode"));public Type<? extends CustomPacketPayload> type(){return TYPE;}}
 @SubscribeEvent public static void login(PlayerEvent.PlayerLoggedInEvent event){if(!enabled()||!(event.getEntity() instanceof ServerPlayer player))return;actor=player.getUUID();stage=0;var level=player.serverLevel();for(int x=-4;x<=10;x++)for(int z=-4;z<=4;z++){level.setBlock(new BlockPos(x,95,z),Blocks.STONE.defaultBlockState(),3);for(int y=96;y<=101;y++)level.setBlock(new BlockPos(x,y,z),Blocks.AIR.defaultBlockState(),3);}for(var pos:new BlockPos[]{SOURCE,TARGET,PEER})level.setBlock(pos,NativeGlassRegistrations.BLOCK.get().defaultBlockState(),3);var source=(NativeGlassEntity)level.getBlockEntity(SOURCE);var raw=source.saveWithoutMetadata(level.registryAccess());raw.putInt("GlassSize",0);raw.putInt("GlassShade",2);raw.putInt("GlassTint",3);raw.putInt("GlassMaterial",7);raw.putInt("GlassTextureLayout",2);raw.putBoolean("GlassStretch",true);raw.putBoolean("GlassFramed",false);raw.putBoolean("GlassJoin",false);raw.putByte("GlassPlaybackMode",(byte)0);raw.putByte("GlassPlaybackSpeed",(byte)2);source.loadWithComponents(raw,level.registryAccess());source.setChanged();level.sendBlockUpdated(SOURCE,source.getBlockState(),source.getBlockState(),3);first=(NativeGlassEntity)level.getBlockEntity(TARGET);second=(NativeGlassEntity)level.getBlockEntity(PEER);first.containedFluids().set(0,new net.neoforged.neoforge.fluids.FluidStack(Fluids.WATER,1000),level.registryAccess());second.containedFluids().set(1,new net.neoforged.neoforge.fluids.FluidStack(Fluids.LAVA,1000),level.registryAccess());water=first.containedFluids().raw(0);lava=second.containedFluids().raw(1);first.setChanged();second.setChanged();player.setGameMode(GameType.SURVIVAL);player.getInventory().clearContent();player.getInventory().selected=0;var tool=new ItemStack(NativeCopifierItemChecks.ITEM);player.setItemInHand(InteractionHand.MAIN_HAND,tool);player.connection.send(new net.minecraft.network.protocol.game.ClientboundSetCarriedItemPacket(0));player.connection.send(new net.minecraft.network.protocol.game.ClientboundContainerSetSlotPacket(-2,0,0,tool.copy()));player.inventoryMenu.broadcastChanges();player.connection.teleport(.5,96,-3,0,0);System.out.println("[vandorlabs][copifier-glass-client] setup PASS Survival/tool/source/twoTargets");}
 private static void apply(ServerPlayer player,int operation){need(player.getUUID().equals(actor)&&operation==stage,"actor/order");need(player.serverLevel().getBlockEntity(TARGET)==first&&player.serverLevel().getBlockEntity(PEER)==second,"same physical owners");need(first.containedFluids().raw(0).equals(water)&&second.containedFluids().raw(1).equals(lava),"both independent fluids unchanged");var clipboard=NativeCopifierClipboard.settings(NativeCopifierItem.data(player.getMainHandItem()));need(clipboard.getInt("glass_tint")==3&&clipboard.getInt("glass_size")==0,"source clipboard retained");if(operation==0){for(var owner:new NativeGlassEntity[]{first,second})need(owner.settings().glass().tint==3&&owner.settings().glass().size==0&&owner.settings().glass().material==7&&!owner.settings().glass().framed&&!owner.settings().glass().join&&owner.settings().playback().mode()==0&&owner.settings().playback().speed()==2,"real connected copied scalar/frame/playback fields");System.out.println("[vandorlabs][copifier-glass-client] applied PASS realSourceCapture/connectedUse/independentFluids");}else if(operation==1){for(var owner:new NativeGlassEntity[]{first,second})need(owner.settings().glass().tint==1&&owner.settings().glass().size==1&&owner.settings().glass().material==-1&&owner.settings().glass().framed&&owner.settings().glass().join,"real undo restores before");System.out.println("[vandorlabs][copifier-glass-client] undo PASS realEditorButton/owners/fluids/clipboard");}else{need(player.containerMenu==player.inventoryMenu,"menu closed");System.out.println("[vandorlabs][copifier-glass-client] completed PASS");}player.serverLevel().setBlock(ACK.east(operation),Blocks.STONE.defaultBlockState(),3);stage++;}
 @SubscribeEvent public static void logout(PlayerEvent.PlayerLoggedOutEvent event){if(enabled()&&event.getEntity().getUUID().equals(actor)){need(stage==3,"all stages complete");System.out.println("[vandorlabs][copifier-glass-client] logout PASS");}}
}
